#!/usr/bin/env python3
"""
SEND_TEST_SOS_VARIETY.py

Sends a batch of SOS packets (alert_type = CRITICAL_SOS only) to
OFFGRID_SOS_RX_HARDCODED.py over UDP, each representing a different
real-world SOS scenario so you can see how the dashboard renders them:

  1. sos_normal           - healthy GPS fix, good battery
  2. sos_low_battery       - battery almost empty
  3. sos_no_gps_fix        - SOS triggered but no usable GPS lock (HDOP invalid)
  4. sos_high_altitude     - beacon at high altitude (mountain/ridge scenario)
  5. sos_weak_signal       - marginal fix, higher HDOP (less accurate GPS)
  6. sos_drifted_location  - new SOS far from the previous fix (tests map re-centering)

All packets are valid, correctly authenticated, registered-device SOS
packets — every one should land as VALID_SOS / CRITICAL on the dashboard,
just with different field values.

Run OFFGRID_SOS_RX_HARDCODED.py first, then run this script.
Requires: pip install cryptography --break-system-packages
"""

import os
import socket
import struct
import time

from cryptography.hazmat.primitives.ciphers.aead import AESGCM

AES_KEY = bytes.fromhex(
    "000102030405060708090A0B0C0D0E0F"
    "101112131415161718191A1B1C1D1E1F"
)
TARGET_HOST = "127.0.0.1"
TARGET_PORT = 40868

DEVICE_ID = 1001  # must be in REGISTERED_DEVICES on the RX side
TAG_ID = b"RFC"
STRUCT_FMT = "<4sIIiihHIBB"
ALERT_SOS = 1

SEQ_DIR = os.path.join(os.path.dirname(__file__), ".seq")
os.makedirs(SEQ_DIR, exist_ok=True)


def next_sequence(name: str) -> int:
    path = os.path.join(SEQ_DIR, f"{name}.seq")
    seq = 1
    if os.path.exists(path):
        try:
            seq = int(open(path).read().strip()) + 1
        except ValueError:
            pass
    with open(path, "w") as f:
        f.write(str(seq))
    return seq


def build_packet(sequence, lat, lon, altitude_m, hdop, battery):
    plaintext = struct.pack(
        STRUCT_FMT,
        TAG_ID.ljust(4, b"\0"),
        DEVICE_ID,
        sequence,
        int(lat * 10_000_000),
        int(lon * 10_000_000),
        altitude_m,
        int(hdop * 100),
        int(time.time()),
        ALERT_SOS,
        battery,
    )
    iv = os.urandom(12)
    aad = struct.pack("<I", DEVICE_ID)
    ct_and_tag = AESGCM(AES_KEY).encrypt(iv, plaintext, aad)
    packet = b"SO" + struct.pack("<I", DEVICE_ID) + iv + ct_and_tag
    assert len(packet) == 64, f"packet is {len(packet)} bytes, expected 64"
    return packet


def send(sock, packet, label):
    sock.sendto(packet, (TARGET_HOST, TARGET_PORT))
    print(f"  sent {label:<22} ({len(packet)} bytes)")
    time.sleep(0.6)  # small gap so the dashboard poll (1s) can pick each one up


# name,                    lat,       lon,      alt(m), hdop,  battery(%)
SCENARIOS = [
    ("sos_normal",           13.0827,   80.2707,  15,     1.05,  88),
    ("sos_low_battery",      13.0790,   80.2650,  12,     1.20,  4),
    ("sos_no_gps_fix",       0.0,       0.0,      0,      99.0,  60),  # hdop*100=9900 -> invalid GPS
    ("sos_high_altitude",    11.4102,   76.6950,  3850,   1.40,  70),
    ("sos_weak_signal",      12.9165,   77.5870,  900,    6.80,  45),
    ("sos_drifted_location", 10.7867,   78.7047,  600,    1.15,  62),
]


def main():
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    print(f"Sending {len(SCENARIOS)} SOS sample packets to {TARGET_HOST}:{TARGET_PORT}\n")

    for name, lat, lon, alt, hdop, batt in SCENARIOS:
        sequence = next_sequence(name)
        packet = build_packet(sequence, lat, lon, alt, hdop, batt)
        send(sock, packet, name)

    sock.close()
    print("\nDone. All six should show up as VALID_SOS / CRITICAL on the")
    print("dashboard, with different location, battery, altitude and GPS values.")


if __name__ == "__main__":
    main()
